import {
  Bodega,
  BodegaProducto,
  InventarioAjuste,
  InventarioAjusteItem,
  Producto,
  sequelize,
} from '../models/index.js';
import { handleSequelizeError } from '../utils/http-error.js';
import { recalcStock } from '../utils/recalc-stock.js';
import { buildAjusteXlsxBuffer } from '../utils/ajuste-xlsx.js';
import { registrarKardex } from '../utils/kardex.js';

function asId(value) {
  const n = Number(value);
  return Number.isInteger(n) && n > 0 ? n : null;
}

function asQty(value) {
  const n = Number(value);
  if (!Number.isInteger(n) || n < 1) {
    return null;
  }
  return n;
}

function asTipo(value) {
  return value === 'menos' ? 'menos' : value === 'mas' ? 'mas' : null;
}

function toItemDto(row) {
  const data = row.toJSON ? row.toJSON() : row;
  return {
    id: data.id,
    id_bodega: data.id_bodega,
    id_producto: data.id_producto,
    sku: data.producto?.sku || '',
    producto: data.producto?.nombre || '',
    bodega: data.bodega?.nombre || '',
    cantidad_anterior: Number(data.cantidad_anterior || 0),
    tipo: data.tipo,
    cantidad_ajuste: Number(data.cantidad_ajuste || 0),
    cantidad_final: Number(data.cantidad_final || 0),
  };
}

function toDto(row) {
  const data = row.toJSON ? row.toJSON() : row;
  const items = Array.isArray(data.items) ? data.items.map(toItemDto) : [];
  return {
    id: data.id,
    descripcion: data.descripcion || '',
    id_usuario: data.id_usuario || null,
    realizado_por: data.realizado_por,
    fecha: data.fecha,
    contabilizado: Boolean(data.contabilizado),
    items,
  };
}

const includeItems = {
  model: InventarioAjusteItem,
  as: 'items',
  include: [
    { model: Producto, as: 'producto', attributes: ['id', 'sku', 'nombre'] },
    { model: Bodega, as: 'bodega', attributes: ['id', 'nombre'] },
  ],
};

async function findAjuste(id) {
  return InventarioAjuste.findByPk(id, {
    include: [includeItems],
    order: [[{ model: InventarioAjusteItem, as: 'items' }, 'id', 'ASC']],
  });
}

export async function listar(_req, res) {
  try {
    const rows = await InventarioAjuste.findAll({
      include: [includeItems],
      order: [
        ['id', 'DESC'],
        [{ model: InventarioAjusteItem, as: 'items' }, 'id', 'ASC'],
      ],
    });
    return res.status(200).json(rows.map(toDto));
  } catch (error) {
    return handleSequelizeError(error, res);
  }
}

export async function obtener(req, res) {
  try {
    const id = asId(req.params.id);
    if (!id) {
      return res.status(400).json({ message: 'El ajuste no es válido' });
    }
    const row = await findAjuste(id);
    if (!row) {
      return res.status(404).json({ message: 'Ajuste no encontrado' });
    }
    return res.status(200).json(toDto(row));
  } catch (error) {
    return handleSequelizeError(error, res);
  }
}

export async function descargarExcel(req, res) {
  try {
    const id = asId(req.params.id);
    if (!id) {
      return res.status(400).json({ message: 'El ajuste no es válido' });
    }
    const row = await findAjuste(id);
    if (!row) {
      return res.status(404).json({ message: 'Ajuste no encontrado' });
    }
    const buffer = buildAjusteXlsxBuffer(toDto(row));
    const filename = `ajuste-${id}.xlsx`;
    res.setHeader(
      'Content-Type',
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    );
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
    res.setHeader('Content-Length', buffer.length);
    return res.status(200).end(buffer);
  } catch (error) {
    return handleSequelizeError(error, res);
  }
}

export async function crear(req, res) {
  const t = await sequelize.transaction();
  try {
    const incoming = Array.isArray(req.body?.items) ? req.body.items : [];
    if (!incoming.length) {
      await t.rollback();
      return res.status(400).json({ message: 'Agrega al menos un producto al ajuste' });
    }

    const descripcion = String(req.body?.descripcion || '').trim();
    const lineas = [];
    const vistos = new Set();

    for (const item of incoming) {
      const idBodega = asId(item.id_bodega);
      const idProducto = asId(item.id_producto);
      const tipo = asTipo(item.tipo);
      const cantidadAjuste = asQty(item.cantidad_ajuste);
      if (!idBodega || !idProducto || !tipo || !cantidadAjuste) {
        await t.rollback();
        return res.status(400).json({
          message: 'Cada línea debe tener bodega, producto, tipo y una cantidad mayor a 0',
        });
      }
      const key = `${idBodega}:${idProducto}`;
      if (vistos.has(key)) {
        await t.rollback();
        return res.status(400).json({ message: 'Hay productos duplicados en el ajuste' });
      }
      vistos.add(key);
      lineas.push({ idBodega, idProducto, tipo, cantidadAjuste });
    }

    const realizados = [];
    for (const linea of lineas) {
      const stock = await BodegaProducto.findOne({
        where: { id_bodega: linea.idBodega, id_producto: linea.idProducto },
        transaction: t,
        lock: t.LOCK.UPDATE,
      });
      if (!stock) {
        await t.rollback();
        return res.status(400).json({
          message: 'Solo puedes ajustar productos ya asignados a la bodega',
        });
      }

      const cantidadAnterior = Number(stock.cantidad || 0);
      const delta = linea.tipo === 'mas' ? linea.cantidadAjuste : -linea.cantidadAjuste;
      const cantidadFinal = cantidadAnterior + delta;
      if (cantidadFinal < 0) {
        await t.rollback();
        return res.status(400).json({
          message: 'La existencia no puede quedar negativa. Reduce la cantidad de ajuste.',
        });
      }

      const [producto, bodega] = await Promise.all([
        Producto.findByPk(linea.idProducto, { transaction: t }),
        Bodega.findByPk(linea.idBodega, { transaction: t }),
      ]);

      stock.cantidad = cantidadFinal;
      await stock.save({ transaction: t });
      realizados.push({
        id_bodega: linea.idBodega,
        id_producto: linea.idProducto,
        cantidad_anterior: cantidadAnterior,
        tipo: linea.tipo,
        cantidad_ajuste: linea.cantidadAjuste,
        cantidad_final: cantidadFinal,
        sku: producto?.sku || '',
        producto: producto?.nombre || '',
        bodega: bodega?.nombre || '',
      });
    }

    const user = req.user || {};
    const ajuste = await InventarioAjuste.create(
      {
        descripcion: descripcion || null,
        id_usuario: asId(user.sub) || null,
        realizado_por: String(user.nombre || user.email || 'Usuario').trim(),
        fecha: new Date(),
        contabilizado: false,
      },
      { transaction: t }
    );

    await InventarioAjusteItem.bulkCreate(
      realizados.map((item) => ({
        id_ajuste: ajuste.id,
        id_bodega: item.id_bodega,
        id_producto: item.id_producto,
        cantidad_anterior: item.cantidad_anterior,
        tipo: item.tipo,
        cantidad_ajuste: item.cantidad_ajuste,
        cantidad_final: item.cantidad_final,
      })),
      { transaction: t }
    );

    await registrarKardex(
      realizados.map((item) => ({
        fecha: ajuste.fecha,
        modulo: 'inventario',
        proceso: item.tipo === 'menos' ? 'salida_ajuste' : 'entrada_ajuste',
        documento_origen: 'ajuste',
        documento: `AJUSTE ${ajuste.id}`,
        id_producto: item.id_producto,
        sku: item.sku,
        producto: item.producto,
        cantidad: item.tipo === 'menos' ? -item.cantidad_ajuste : item.cantidad_ajuste,
        id_bodega: item.id_bodega,
        bodega: item.bodega,
        usuario: ajuste.realizado_por,
      })),
      t
    );

    await recalcStock(
      realizados.map((item) => item.id_producto),
      t
    );
    await t.commit();

    const created = await findAjuste(ajuste.id);
    return res.status(201).json(toDto(created));
  } catch (error) {
    await t.rollback();
    return handleSequelizeError(error, res);
  }
}

import {
  Bodega,
  BodegaProducto,
  Compra,
  CompraItem,
  Producto,
  Proveedor,
  sequelize,
} from '../models/index.js';
import { handleSequelizeError } from '../utils/http-error.js';
import { registrarKardex } from '../utils/kardex.js';
import { recalcStock } from '../utils/recalc-stock.js';

const IVA_RATE = 0.12;

function roundMoney(value) {
  return Math.round(Number(value) * 100) / 100;
}

function nextNumero(lastId) {
  return `COM-${String((lastId || 0) + 1).padStart(6, '0')}`;
}

const includeCompra = [
  {
    model: Proveedor,
    as: 'proveedor',
    attributes: ['id', 'nombre', 'razon_social', 'nombre_comercial', 'nit', 'email', 'telefono', 'direccion'],
  },
  {
    model: CompraItem,
    as: 'items',
    include: [{ model: Producto, as: 'producto', attributes: ['id', 'sku', 'nombre', 'tipo'] }],
  },
];

export async function listar(_req, res) {
  try {
    const rows = await Compra.findAll({ include: includeCompra, order: [['id', 'DESC']] });
    return res.status(200).json(rows);
  } catch (error) {
    return handleSequelizeError(error, res);
  }
}

export async function obtenerPorId(req, res) {
  try {
    const row = await Compra.findByPk(req.params.id, { include: includeCompra });
    if (!row) {
      return res.status(404).json({ message: 'Compra no encontrada' });
    }
    return res.status(200).json(row);
  } catch (error) {
    return handleSequelizeError(error, res);
  }
}

export async function crear(req, res) {
  const t = await sequelize.transaction();
  try {
    const {
      id_proveedor,
      id_bodega,
      numero_proveedor,
      metodo_pago,
      condicion_venta,
      moneda,
      vendedor,
      canal,
      requerimientos,
      plazo,
      plazo_unidad,
      vencimiento,
      notas,
      fecha,
      descuento: descuentoIn,
      items,
    } = req.body || {};

    if (!id_proveedor) {
      await t.rollback();
      return res.status(400).json({ message: 'Selecciona un proveedor' });
    }
    if (!Array.isArray(items) || items.length === 0) {
      await t.rollback();
      return res.status(400).json({ message: 'Agrega al menos un producto a la compra' });
    }

    const proveedor = await Proveedor.findByPk(id_proveedor, { transaction: t });
    if (!proveedor || !proveedor.estado) {
      await t.rollback();
      return res.status(400).json({ message: 'El proveedor indicado no existe o está inactivo' });
    }

    const metodos = ['efectivo', 'tarjeta', 'transferencia'];
    const pago = metodos.includes(metodo_pago) ? metodo_pago : 'efectivo';
    const condicion = condicion_venta === 'credito' ? 'credito' : 'contado';
    const unidades = ['dias', 'meses', 'anio'];
    const unidad = unidades.includes(plazo_unidad) ? plazo_unidad : 'dias';

    let bodega = null;
    if (id_bodega) {
      bodega = await Bodega.findByPk(id_bodega, { transaction: t });
    }
    if (!bodega) {
      bodega = await Bodega.findOne({ where: { principal: true, estado: true }, transaction: t });
    }

    const lineas = [];
    let subtotal = 0;
    let ivaTotal = 0;
    let descLineas = 0;

    for (const item of items) {
      const cantidad = Number(item.cantidad);
      if (!item.id_producto || !Number.isInteger(cantidad) || cantidad < 1) {
        await t.rollback();
        return res.status(400).json({ message: 'Cada línea debe tener producto y cantidad válida' });
      }
      const producto = await Producto.findByPk(item.id_producto, { transaction: t, lock: t.LOCK.UPDATE });
      if (!producto || !producto.estado) {
        await t.rollback();
        return res.status(400).json({ message: 'Uno de los productos no existe o está inactivo' });
      }
      const precio = roundMoney(Number(item.precio_unitario ?? producto.costo_compra) || 0);
      const desc = roundMoney(Math.max(0, Number(item.descuento) || 0));
      const bruto = roundMoney(precio * cantidad);
      const gravable = roundMoney(Math.max(0, bruto - desc));
      const iva = roundMoney(gravable * IVA_RATE);
      const totalLinea = roundMoney(gravable + iva);
      subtotal = roundMoney(subtotal + bruto);
      descLineas = roundMoney(descLineas + desc);
      ivaTotal = roundMoney(ivaTotal + iva);
      lineas.push({ producto, cantidad, precio, desc, gravable, iva, totalLinea });
    }

    const descuentoExtra = roundMoney(Math.max(0, Number(descuentoIn) || 0));
    const descuento = roundMoney(descLineas + descuentoExtra);
    const gravableDoc = roundMoney(Math.max(0, subtotal - descuento));
    const iva = roundMoney(gravableDoc * IVA_RATE);
    const total = roundMoney(gravableDoc + iva);

    const ultima = await Compra.findOne({ order: [['id', 'DESC']], transaction: t, lock: t.LOCK.UPDATE });
    const fechaEmision = fecha ? new Date(fecha) : null;

    const compra = await Compra.create(
      {
        numero: nextNumero(ultima?.id),
        numero_proveedor: String(numero_proveedor || '').trim() || null,
        id_proveedor,
        id_bodega: bodega?.id || null,
        ...(fechaEmision && !Number.isNaN(fechaEmision.getTime()) ? { fecha: fechaEmision } : {}),
        metodo_pago: pago,
        condicion_venta: condicion,
        moneda: String(moneda || 'Quetzal').trim() || 'Quetzal',
        vendedor: String(vendedor || req.user?.nombre || '').trim() || null,
        canal: String(canal || '').trim() || null,
        requerimientos: String(requerimientos || '').trim() || null,
        plazo: Math.max(0, Number(plazo) || 0),
        plazo_unidad: unidad,
        vencimiento: vencimiento || null,
        notas: notas ? String(notas).trim() : null,
        descuento,
        subtotal: gravableDoc,
        iva,
        total,
        archivado: false,
        estado: condicion === 'credito' ? 'pendiente' : 'cancelada',
      },
      { transaction: t }
    );

    for (const linea of lineas) {
      await CompraItem.create(
        {
          id_compra: compra.id,
          id_producto: linea.producto.id,
          descripcion: linea.producto.nombre,
          cantidad: linea.cantidad,
          precio_unitario: linea.precio,
          descuento: linea.desc,
          subtotal: linea.gravable,
          iva: linea.iva,
          total: linea.totalLinea,
        },
        { transaction: t }
      );

      const esServicio =
        linea.producto.tipo === 'servicio' ||
        String(linea.producto.categoria || '').toLowerCase().includes('servicio');
      if (esServicio) {
        continue;
      }

      let stock = null;
      if (bodega) {
        stock = await BodegaProducto.findOne({
          where: { id_bodega: bodega.id, id_producto: linea.producto.id },
          transaction: t,
          lock: t.LOCK.UPDATE,
        });
        if (!stock) {
          stock = await BodegaProducto.create(
            { id_bodega: bodega.id, id_producto: linea.producto.id, cantidad: 0 },
            { transaction: t }
          );
        }
        stock.cantidad = Number(stock.cantidad) + linea.cantidad;
        await stock.save({ transaction: t });
        await recalcStock([linea.producto.id], t);
      } else {
        await linea.producto.update(
          { stock_actual: Number(linea.producto.stock_actual) + linea.cantidad },
          { transaction: t, validate: false }
        );
      }

      await registrarKardex(
        [
          {
            modulo: 'compras',
            proceso: 'entrada_compra',
            documento_origen: 'compra',
            documento: compra.numero,
            id_producto: linea.producto.id,
            sku: linea.producto.sku,
            producto: linea.producto.nombre,
            cantidad: linea.cantidad,
            id_bodega: bodega?.id || null,
            bodega: bodega?.nombre || '',
            usuario: String(req.user?.nombre || req.user?.email || '').trim(),
          },
        ],
        t
      );
    }

    await t.commit();
    const creada = await Compra.findByPk(compra.id, { include: includeCompra });
    return res.status(201).json(creada);
  } catch (error) {
    await t.rollback();
    return handleSequelizeError(error, res);
  }
}

export async function actualizar(req, res) {
  const t = await sequelize.transaction();
  try {
    const row = await Compra.findByPk(req.params.id, {
      include: includeCompra,
      transaction: t,
      lock: t.LOCK.UPDATE,
    });
    if (!row) {
      await t.rollback();
      return res.status(404).json({ message: 'Compra no encontrada' });
    }

    const { archivado, estado } = req.body || {};
    const patch = {};
    if (typeof archivado === 'boolean') {
      patch.archivado = archivado;
    }

    if (estado) {
      if (!['pendiente', 'cancelada', 'anulada'].includes(estado)) {
        await t.rollback();
        return res.status(400).json({ message: 'Estado inválido' });
      }
      if (estado === 'anulada' && row.estado !== 'anulada') {
        await revertirInventario(row, req.user, t);
      }
      patch.estado = estado;
    }

    await row.update(patch, { transaction: t });
    await t.commit();
    const actualizada = await Compra.findByPk(row.id, { include: includeCompra });
    return res.status(200).json(actualizada);
  } catch (error) {
    await t.rollback();
    return handleSequelizeError(error, res);
  }
}

async function revertirInventario(compra, user, t) {
  const bodega = compra.id_bodega ? await Bodega.findByPk(compra.id_bodega, { transaction: t }) : null;
  for (const linea of compra.items || []) {
    const producto = linea.producto || (await Producto.findByPk(linea.id_producto, { transaction: t }));
    if (!producto) {
      continue;
    }
    const esServicio =
      producto.tipo === 'servicio' || String(producto.categoria || '').toLowerCase().includes('servicio');
    if (esServicio) {
      continue;
    }
    const cantidad = Number(linea.cantidad) || 0;
    if (bodega) {
      const stock = await BodegaProducto.findOne({
        where: { id_bodega: bodega.id, id_producto: producto.id },
        transaction: t,
        lock: t.LOCK.UPDATE,
      });
      if (stock) {
        stock.cantidad = Math.max(0, Number(stock.cantidad) - cantidad);
        await stock.save({ transaction: t });
        await recalcStock([producto.id], t);
      }
    } else {
      await producto.update(
        { stock_actual: Math.max(0, Number(producto.stock_actual) - cantidad) },
        { transaction: t, validate: false }
      );
    }
    await registrarKardex(
      [
        {
          modulo: 'compras',
          proceso: 'anular_compra',
          documento_origen: 'compra',
          documento: compra.numero,
          id_producto: producto.id,
          sku: producto.sku,
          producto: producto.nombre,
          cantidad: -cantidad,
          id_bodega: bodega?.id || null,
          bodega: bodega?.nombre || '',
          usuario: String(user?.nombre || user?.email || '').trim(),
        },
      ],
      t
    );
  }
}

import {
  Bodega,
  BodegaProducto,
  Cliente,
  Factura,
  FacturaItem,
  InventarioDevolucion,
  InventarioDevolucionItem,
  Producto,
  sequelize,
} from '../models/index.js';
import { handleSequelizeError } from '../utils/http-error.js';
import { recalcStock } from '../utils/recalc-stock.js';
import { registrarKardex } from '../utils/kardex.js';

const ITBIS_RATE = 0.18;
const RAZONES = ['danado', 'vencido', 'no_gusto', 'cambio_producto'];
const RESTOCK = {
  danado: false,
  vencido: false,
  no_gusto: true,
  cambio_producto: true,
};

function asId(value) {
  const n = Number(value);
  return Number.isInteger(n) && n > 0 ? n : null;
}

function asQty(value) {
  const n = Number(value);
  if (!Number.isInteger(n) || n < 1) {
    return null;
  }
  return n;
}

function roundMoney(value) {
  return Math.round(Number(value || 0) * 100) / 100;
}

function nextNumero(prefix, lastId) {
  return `${prefix}-${String((lastId || 0) + 1).padStart(6, '0')}`;
}

function asRazon(value) {
  return RAZONES.includes(value) ? value : null;
}

async function stockBodega(idBodega, idProducto, transaction) {
  let stock = await BodegaProducto.findOne({
    where: { id_bodega: idBodega, id_producto: idProducto },
    transaction,
    lock: transaction.LOCK.UPDATE,
  });
  if (!stock) {
    stock = await BodegaProducto.create(
      { id_bodega: idBodega, id_producto: idProducto, cantidad: 0 },
      { transaction }
    );
  }
  return stock;
}

function toItemDto(row) {
  const data = row.toJSON ? row.toJSON() : row;
  return {
    id: data.id,
    id_factura_item: data.id_factura_item,
    id_producto: data.id_producto,
    sku: data.producto?.sku || '',
    producto: data.producto?.nombre || '',
    cantidad: Number(data.cantidad || 0),
    precio_unitario: roundMoney(data.precio_unitario),
    subtotal: roundMoney(data.subtotal),
    restablece_stock: Boolean(data.restablece_stock),
    cantidad_anterior: Number(data.cantidad_anterior || 0),
    cantidad_final: Number(data.cantidad_final || 0),
    id_producto_cambio: data.id_producto_cambio || null,
    sku_cambio: data.producto_cambio?.sku || '',
    producto_cambio: data.producto_cambio?.nombre || '',
    cantidad_cambio: Number(data.cantidad_cambio || 0),
    precio_cambio: roundMoney(data.precio_cambio),
    subtotal_cambio: roundMoney(data.subtotal_cambio),
    cantidad_anterior_cambio:
      data.cantidad_anterior_cambio == null ? null : Number(data.cantidad_anterior_cambio),
    cantidad_final_cambio: data.cantidad_final_cambio == null ? null : Number(data.cantidad_final_cambio),
  };
}

function toDto(row) {
  const data = row.toJSON ? row.toJSON() : row;
  const items = Array.isArray(data.items) ? data.items.map(toItemDto) : [];
  return {
    id: data.id,
    numero: data.numero,
    referencia_nc: data.referencia_nc || '',
    id_factura: data.id_factura,
    factura: data.factura?.numero || '',
    id_cliente: data.id_cliente,
    cliente: data.cliente?.nombre || '',
    id_bodega: data.id_bodega,
    bodega: data.bodega?.nombre || '',
    razon: data.razon,
    resolucion: data.resolucion,
    observacion: data.observacion || '',
    subtotal_devuelto: roundMoney(data.subtotal_devuelto),
    itbis_devuelto: roundMoney(data.itbis_devuelto),
    total_devuelto: roundMoney(data.total_devuelto),
    subtotal_cambio: roundMoney(data.subtotal_cambio),
    itbis_cambio: roundMoney(data.itbis_cambio),
    total_cambio: roundMoney(data.total_cambio),
    diferencia: roundMoney(data.diferencia),
    reembolso: roundMoney(data.reembolso),
    cobro: roundMoney(data.cobro),
    nota_credito_monto: roundMoney(data.nota_credito_monto),
    valor_inventario: roundMoney(data.valor_inventario),
    contabilizado: Boolean(data.contabilizado),
    realizado_por: data.realizado_por,
    fecha: data.fecha,
    items,
  };
}

const includeItems = {
  model: InventarioDevolucionItem,
  as: 'items',
  include: [
    { model: Producto, as: 'producto', attributes: ['id', 'sku', 'nombre'] },
    { model: Producto, as: 'producto_cambio', attributes: ['id', 'sku', 'nombre'] },
  ],
};

async function findDevolucion(id) {
  return InventarioDevolucion.findByPk(id, {
    include: [
      includeItems,
      { model: Factura, as: 'factura', attributes: ['id', 'numero'] },
      { model: Cliente, as: 'cliente', attributes: ['id', 'nombre'] },
      { model: Bodega, as: 'bodega', attributes: ['id', 'nombre'] },
    ],
    order: [[{ model: InventarioDevolucionItem, as: 'items' }, 'id', 'ASC']],
  });
}

async function cantidadesDevueltas(idFactura, transaction) {
  const previas = await InventarioDevolucion.findAll({
    where: { id_factura: idFactura },
    include: [{ model: InventarioDevolucionItem, as: 'items' }],
    transaction,
  });
  const map = new Map();
  for (const doc of previas) {
    for (const row of doc.items || []) {
      map.set(row.id_factura_item, (map.get(row.id_factura_item) || 0) + Number(row.cantidad || 0));
    }
  }
  return map;
}

export async function listar(_req, res) {
  try {
    const rows = await InventarioDevolucion.findAll({
      include: [
        includeItems,
        { model: Factura, as: 'factura', attributes: ['id', 'numero'] },
        { model: Cliente, as: 'cliente', attributes: ['id', 'nombre'] },
        { model: Bodega, as: 'bodega', attributes: ['id', 'nombre'] },
      ],
      order: [
        ['id', 'DESC'],
        [{ model: InventarioDevolucionItem, as: 'items' }, 'id', 'ASC'],
      ],
    });
    return res.status(200).json(rows.map(toDto));
  } catch (error) {
    return handleSequelizeError(error, res);
  }
}

export async function obtener(req, res) {
  try {
    const id = asId(req.params.id);
    if (!id) {
      return res.status(400).json({ message: 'La devolución no es válida' });
    }
    const row = await findDevolucion(id);
    if (!row) {
      return res.status(404).json({ message: 'Devolución no encontrada' });
    }
    return res.status(200).json(toDto(row));
  } catch (error) {
    return handleSequelizeError(error, res);
